-- Audit only. Run as a privileged operator in a READ ONLY, REPEATABLE READ
-- transaction with statement_timeout and lock_timeout. Never expose this result
-- through a player RPC or commit the export: it contains investigation IDs.
-- Uses the exact deployed disposable-domain policy; no full email, IP, token,
-- message content or password leaves the database.
with scope_snapshot(data) as materialized (
with disposable as materialized (
 select u.id,u.created_at,u.email_confirmed_at,u.last_sign_in_at,u.banned_until,public.signup_email_domain(u.email) email_domain,p.pseudo,p.bonus_regular_packs,p.karas_balance
 from auth.users u left join public.user_profiles p on p.user_id=u.id where public.is_disposable_email(u.email)
), relevant as materialized (select r.* from public.referrals r where r.referred_id in(select id from disposable)), actors as materialized (select id from disposable union select referrer_id from relevant)
select json_build_object(
 'snapshot',now(), 'registry',(select max(version) from supabase_migrations.schema_migrations),
 'disposable',(select coalesce(json_agg(d order by created_at),'[]') from disposable d),
 'referrals',(select coalesce(json_agg(r order by created_at),'[]') from relevant r),
 'referrerStats',(select coalesce(json_agg(x),'[]') from(select a.id,p.pseudo,p.bonus_regular_packs,p.karas_balance,u.created_at,u.last_sign_in_at,u.banned_until,count(r.id) total_referrals,count(r.id) filter(where r.rewarded_at is not null) rewarded_referrals,coalesce(sum(r.reward_packs) filter(where r.rewarded_at is not null),0) total_packs_awarded,(select regular_packs_opened from public.user_achievement_stats s where s.user_id=a.id) lifetime_regular_packs_opened,(select count(*) from public.user_cards c where c.user_id=a.id) current_cards from actors a join auth.users u on u.id=a.id left join public.user_profiles p on p.user_id=a.id left join public.referrals r on r.referrer_id=a.id group by a.id,p.pseudo,p.bonus_regular_packs,p.karas_balance,u.created_at,u.last_sign_in_at,u.banned_until)x),
 'allActorReferrals',(select coalesce(json_agg(r order by r.created_at),'[]') from public.referrals r where r.referrer_id in(select id from actors) or r.referred_id in(select id from actors)),
 'counts',json_build_object('allUsers',(select count(*) from auth.users),'referrals',(select count(*) from public.referrals),'auctionsInvolvingActors',(select count(*) from public.auctions where seller_id in(select id from actors) or buyer_id in(select id from actors)),'tradesInvolvingActors',(select count(*) from public.trade_offers where from_user in(select id from actors) or to_user in(select id from actors))),
 'referralCodeOwnerMismatches',(select count(*) from relevant r join public.referral_codes c on c.id=r.code_id where c.user_id<>r.referrer_id),
 'metadataEvidence',json_build_object('regularPackRows',(select count(*) from information_schema.tables where table_schema='public' and table_name in('regular_packs','regular_pack_openings','pack_openings','booster_openings','wallet_transactions','kara_transactions')),'ipDeviceColumns',(select coalesce(json_agg(table_name||'.'||column_name),'[]') from information_schema.columns where table_schema='public' and column_name ~* '(^ip$|ip_address|device_id|fingerprint)')))
),
economy_snapshot(data) as materialized (
with disposable as materialized(select u.id from auth.users u where public.is_disposable_email(u.email)), actors as materialized(select id from disposable union select referrer_id from public.referrals where referred_id in(select id from disposable)), direct_trades as materialized(select * from public.trade_offers where from_user in(select id from actors) or to_user in(select id from actors)), direct_auctions as materialized(select * from public.auctions where seller_id in(select id from actors) or buyer_id in(select id from actors)), instances as materialized(select id from public.user_cards where user_id in(select id from actors) union select card_instance_id from direct_auctions union select unnest(offered_card_ids||requested_card_ids) from direct_trades)
select json_build_object(
 'snapshot',now(),
 'auctions',(select coalesce(json_agg(json_build_object('id',a.id,'card_instance_id',a.card_instance_id,'seller_id',a.seller_id,'buyer_id',a.buyer_id,'status',a.status,'current_price',a.current_price,'starting_price',a.starting_price,'created_at',a.created_at,'ends_at',a.ends_at,'snapshotCardId',a.card_snapshot->>'id','snapshotName',a.card_snapshot->>'name') order by a.created_at),'[]') from public.auctions a where a.card_instance_id in(select id from instances) or a.seller_id in(select id from actors) or a.buyer_id in(select id from actors)),
 'trades',(select coalesce(json_agg(json_build_object('id',t.id,'from_user',t.from_user,'to_user',t.to_user,'offered_card_ids',t.offered_card_ids,'requested_card_ids',t.requested_card_ids,'offered_karas',t.offered_karas,'requested_karas',t.requested_karas,'status',t.status,'created_at',t.created_at,'updated_at',t.updated_at,'parent_offer_id',t.parent_offer_id) order by t.updated_at),'[]') from public.trade_offers t where t.from_user in(select id from actors) or t.to_user in(select id from actors) or t.offered_card_ids && array(select id from instances) or t.requested_card_ids && array(select id from instances)),
 'instances',(select coalesce(json_agg(json_build_object('instance_id',i.id,'current_user_id',c.user_id,'card_id',c.card_id,'obtained_at',c.date_obtention,'rarity',c.rarity,'shiny',c.is_shiny,'evolved',c.is_evolved,'is_first_owner',c.is_first_owner,'is_locked',c.is_locked) order by i.id),'[]') from instances i left join public.user_cards c on c.id=i.id),
 'actorStats',(select coalesce(json_agg(json_build_object('user_id',a.id,'stats',json_build_object('regular_packs_opened',s.regular_packs_opened,'decision_packs_opened',to_jsonb(s)->'decision_packs_opened','trades_completed',to_jsonb(s)->'trades_completed'),'decisionPacks',(select count(*) from public.decision_packs p where p.user_id=a.id),'auctionsSold',(select count(*) from public.auctions x where x.seller_id=a.id and x.status='sold'),'acceptedTrades',(select count(*) from public.trade_offers t where (t.from_user=a.id or t.to_user=a.id) and t.status='accepted'),'activeSellerAuctions',(select count(*) from public.auctions x where x.seller_id=a.id and x.status='active'),'activeWinningAuctions',(select count(*) from public.auctions x where x.buyer_id=a.id and x.status='active'),'historicalBids',(select count(*) from public.bids b where b.bidder_id=a.id),'is_admin',exists(select 1 from public.admin_users z where z.user_id=a.id))),'[]') from actors a left join public.user_achievement_stats s on s.user_id=a.id),
 'authAuditMetadata',(select json_build_object('count',count(*),'oldest',min(created_at),'newest',max(created_at)) from auth.audit_log_entries),
 'constraints',(select json_agg(json_build_object('table',c.conrelid::regclass::text,'name',c.conname,'definition',pg_get_constraintdef(c.oid))) from pg_constraint c where c.conrelid=any(array['public.user_profiles'::regclass,'public.notifications'::regclass,'public.admin_audit_logs'::regclass,'public.user_cards'::regclass,'public.auctions'::regclass,'public.trade_offers'::regclass])))
),
correlations_snapshot(data) as materialized (
with disposable as materialized(select u.id from auth.users u where public.is_disposable_email(u.email)), actors as materialized(select id from disposable union select referrer_id from public.referrals where referred_id in(select id from disposable)), events as materialized(select a.created_at,a.payload->>'actor_id' actor_id,a.payload->>'action' action,nullif(btrim(a.ip_address),'') ip from auth.audit_log_entries a where a.payload->>'actor_id' in(select id::text from actors)), ip_users as materialized(select distinct a.payload->>'actor_id' actor_id,nullif(btrim(a.ip_address),'') ip from auth.audit_log_entries a where a.payload->>'action' in('user_signedup','login') and nullif(btrim(a.ip_address),'') is not null)
select json_build_object(
 'snapshot',now(),
 'events',(select coalesce(json_agg(json_build_object('user_id',x.actor_id,'action',x.action,'count',x.n,'first',x.first,'last',x.last,'eventsWithIp',x.ip_n)),'[]') from(select actor_id,action,count(*) n,min(created_at) first,max(created_at) last,count(ip) ip_n from events group by actor_id,action)x),
 'sharedIpSignals',(select coalesce(json_agg(x),'[]') from(select a.actor_id user_a,b.actor_id user_b,count(distinct a.ip) common_ip_count,max((select count(*) from ip_users p where p.ip=a.ip)) max_users_on_shared_ip from ip_users a join ip_users b on a.ip=b.ip and a.actor_id<b.actor_id where a.actor_id in(select id::text from actors) and b.actor_id in(select id::text from actors) group by a.actor_id,b.actor_id)x),
 'actorIpCoverage',(select count(*) from events where ip is not null),
 'ruleSnapshot',json_build_object('rules',(select count(*) from public.signup_email_domain_rules),'registry',(select max(version) from supabase_migrations.schema_migrations)))
),
domainHistory_snapshot(data) as materialized (
with disposable as materialized(select id from auth.users where public.is_disposable_email(email)), actors as materialized(select id from disposable union select referrer_id from public.referrals where referred_id in(select id from disposable))
select json_build_object('snapshot',now(),'events',(select coalesce(json_agg(json_build_object('user_id',a.payload->>'actor_id','action',a.payload->>'action','created_at',a.created_at,'email_domain',public.signup_email_domain(a.payload->>'actor_username'),'domain_disposable',public.is_disposable_email(a.payload->>'actor_username')) order by a.created_at),'[]') from auth.audit_log_entries a where a.payload->>'actor_id' in(select id::text from actors) and a.payload->>'action' in('user_signedup','user_modified','user_confirmation_requested')))
)
select json_build_object('scope',(select data from scope_snapshot),'economy',(select data from economy_snapshot),'correlations',(select data from correlations_snapshot),'domainHistory',(select data from domainHistory_snapshot));
